ALTER POLICY "Anyone can submit career applications" ON public.career_applications WITH CHECK (length(btrim(full_name)) BETWEEN 1 AND 200 AND length(btrim(email)) BETWEEN 3 AND 320 AND length(btrim(phone)) BETWEEN 3 AND 40 AND length(btrim(position)) BETWEEN 1 AND 200 AND experience_years BETWEEN 0 AND 80 AND length(cover_letter) <= 20000);
ALTER POLICY "Anyone can insert screenings" ON public.corporate_screenings WITH CHECK (company_id IS NOT NULL AND employee_id IS NOT NULL);
ALTER POLICY "Anyone can log service interest" ON public.corporate_service_interests WITH CHECK (coalesce(length(message),0) <= 5000 AND coalesce(length(contact_name),0) <= 200 AND coalesce(length(contact_email),0) <= 320 AND coalesce(length(contact_phone),0) <= 40);
ALTER POLICY "Anyone can insert crisis alerts" ON public.corporate_crisis_alerts WITH CHECK (company_id IS NOT NULL AND employee_id IS NOT NULL AND level BETWEEN 0 AND 10);
ALTER POLICY "Anyone can insert WHO-5 sessions" ON public.who5_sessions WITH CHECK (length(btrim(session_id)) BETWEEN 1 AND 200);
ALTER POLICY "Anyone can submit session feedback" ON public.session_feedback WITH CHECK (star_rating BETWEEN 1 AND 5 AND length(btrim(session_code)) BETWEEN 1 AND 50 AND length(btrim(therapist_name)) BETWEEN 1 AND 200);
ALTER POLICY "Anyone can submit reviews" ON public.specialist_reviews WITH CHECK (rating BETWEEN 1 AND 5 AND specialist_id IS NOT NULL AND length(btrim(reviewer_name)) BETWEEN 1 AND 200);
ALTER POLICY "Anyone can insert whisper events" ON public.whisper_events WITH CHECK (whisper_id IS NOT NULL AND length(btrim(event_type)) BETWEEN 1 AND 100);
ALTER POLICY "Anyone can insert CTA clicks" ON public.who5_cta_clicks WITH CHECK (length(btrim(session_id)) BETWEEN 1 AND 200 AND length(btrim(cta_type)) BETWEEN 1 AND 100);
ALTER POLICY "Anyone can submit a deletion request" ON public.account_deletion_requests WITH CHECK (length(btrim(full_name)) BETWEEN 1 AND 200 AND length(btrim(email)) BETWEEN 3 AND 320);
ALTER POLICY "Anyone can submit a chat lead" ON public.chat_leads WITH CHECK (coalesce(length(name),0) <= 200 AND coalesce(length(phone),0) <= 40 AND coalesce(length(email),0) <= 320 AND coalesce(length(message),0) <= 5000 AND handled_by IS NULL);
ALTER POLICY "Public can submit screening bookings" ON public.corporate_screening_bookings WITH CHECK (length(btrim(company_name)) BETWEEN 1 AND 200 AND length(btrim(contact_name)) BETWEEN 1 AND 200 AND length(btrim(contact_email)) BETWEEN 3 AND 320);
ALTER POLICY "Anyone can insert callback requests" ON public.callback_requests WITH CHECK (length(btrim(full_name)) BETWEEN 1 AND 200 AND length(btrim(phone_number)) BETWEEN 3 AND 40 AND wellbeing_percentage BETWEEN 0 AND 100);
ALTER POLICY "Anyone can subscribe to newsletter" ON public.newsletter_subscribers WITH CHECK (length(btrim(email)) BETWEEN 3 AND 320 AND email LIKE '%@%');
ALTER POLICY "Anyone can register for trainings" ON public.training_registrations WITH CHECK (training_id IS NOT NULL AND length(btrim(full_name)) BETWEEN 1 AND 200 AND length(btrim(email)) BETWEEN 3 AND 320 AND length(btrim(phone_number)) BETWEEN 3 AND 40);
ALTER POLICY "Anyone can insert chat messages" ON public.chat_messages WITH CHECK (session_id IS NOT NULL AND role IN ('user','assistant') AND length(content) BETWEEN 1 AND 20000);
ALTER POLICY "Anyone can insert assessment sessions" ON public.assessment_sessions WITH CHECK (length(btrim(session_id)) BETWEEN 1 AND 200 AND length(btrim(test_type)) BETWEEN 1 AND 100 AND total_questions BETWEEN 0 AND 500);
ALTER POLICY "Anyone can submit a whisper" ON public.whispers WITH CHECK (length(btrim(audio_path)) BETWEEN 1 AND 500);
ALTER POLICY "Anyone can submit contact form" ON public.contact_submissions WITH CHECK (length(btrim(name)) BETWEEN 1 AND 200 AND length(btrim(email)) BETWEEN 3 AND 320 AND length(btrim(subject)) BETWEEN 1 AND 300 AND length(btrim(message)) BETWEEN 1 AND 10000);
ALTER POLICY "Anyone can insert assessment emails" ON public.assessment_emails WITH CHECK (length(btrim(email)) BETWEEN 3 AND 320 AND length(btrim(session_id)) BETWEEN 1 AND 200 AND length(btrim(test_type)) BETWEEN 1 AND 100);
ALTER POLICY "Anyone can view specialist certificates" ON public.specialist_certificates USING (EXISTS (SELECT 1 FROM public.specialists s WHERE s.id = specialist_certificates.specialist_id AND s.is_active));
ALTER POLICY "Anyone can upload resumes" ON storage.objects WITH CHECK (bucket_id = 'resumes' AND coalesce(array_length(storage.foldername(name),1),0) = 0 AND lower(storage.extension(name)) IN ('pdf','doc','docx'));